"""Illustrated controller-specific Audio/Loop recording and bounce workflows."""

def enrich(chapters,language='en'):
    de=language=='de'
    def text(en,german):return german if de else en
    def variant(micro,large):return dict(mikro=micro,mk1=large,mk2=large)
    ch=next(c for c in chapters if c.get('source_title',c['title'])=='Sampling: choose an input and record')
    ch['steps'][2]=text('Choose DETECT for threshold recording, SYNC for a timed sampler take, or LOOP for a timed take that becomes an AUDIO Sound. Set threshold or BARS before arming.','Wähle DETECT für eine pegelgesteuerte Aufnahme, SYNC für einen zeitlich begrenzten Sampler-Take oder LOOP für einen Take als AUDIO-Sound. Stelle Threshold beziehungsweise BARS vor dem Scharfstellen ein.')
    ch.setdefault('supplements',[]).extend([
        dict(title=text('Sampling: AUDIO Sounds and loop recording','Sampling: AUDIO-Sounds und Loop-Aufnahme'),
             intro=text('An AUDIO Sound plays a recording in time with its Group Pattern without needing MIDI trigger notes. Its source is still a sample file; insert effects and normal channel routing remain available.','Ein AUDIO-Sound spielt eine Aufnahme synchron zum Group-Pattern, ohne auslösende MIDI-Noten. Die Quelle bleibt eine Sample-Datei. Insert-Effekte und normale Kanalrouten stehen weiter bereit.'),figures=['Sampling / AUDIO LOOP'],images=[],
             steps=[text('Choose an empty target pad in RECORD. For an internal recording select INTERNAL, then GROUP, MASTER or SOUND with its Group/pad number. For an external recording select the connected input.','Wähle in RECORD ein leeres Zielpad. Intern wählst du INTERNAL und dann GROUP, MASTER oder SOUND mit Group-/Pad-Nummer. Extern wählst du den angeschlossenen Eingang.'),
                    text('Set MODE LOOP and BARS, for example 1. START arms the take; PLAY starts the transport. Recording begins at the next bar and finishes after the selected length. The take becomes an AUDIO Sound.','Setze MODE LOOP und beispielsweise BARS 1. START schaltet scharf, PLAY startet den Transport. Die Aufnahme beginnt am nächsten Takt und endet nach der gewählten Länge. Der Take wird zum AUDIO-Sound.'),
                    variant(text('In RECORD hold SHIFT and press F2 AUDIO. Arrows select a field; turn the encoder to edit it.','Halte in RECORD SHIFT und drücke F2 AUDIO. Die Pfeile wählen das Feld, der Encoder ändert es.'),text('In RECORD hold SHIFT and press display button 6 AUDIO. Encoders 1-4 edit MODE, BARS, STRETCH and TUNE.','Halte in RECORD SHIFT und drücke Displaytaste 6 AUDIO. Encoder 1-4 ändern MODE, BARS, STRETCH und TUNE.')),
                    text('MODE AUDIO loops an existing sample. BARS is its musical length; STRETCH preserves pitch as tempo changes, OFF changes playback rate. TUNE transposes. MODE SAMPLER restores note-triggered playback.','MODE AUDIO loopt ein vorhandenes Sample. BARS ist seine musikalische Länge. STRETCH erhält die Tonhöhe bei Tempoänderungen, OFF verändert die Abspielrate. TUNE transponiert. MODE SAMPLER stellt die Notensteuerung wieder her.')],
             notes=[(text('Transport and Pattern','Transport und Pattern'),text('The Group needs an active clip. STOP silences playback; RESTART and locating change audio phase. A short Pattern restarts the recording early, a long one repeats it. Tapping the pad during playback does not add a duplicate one-shot. MIDI-gated Audio playback is not provided.','Die Group benötigt einen aktiven Clip. STOP beendet die Wiedergabe; RESTART und Positionswechsel ändern die Audioposition. Kurze Patterns starten die Aufnahme früher neu, lange wiederholen sie. Pad-Anschläge starten während der Wiedergabe keinen zusätzlichen One-Shot. Ein MIDI-gesteuerter Audio-Gate-Modus ist nicht enthalten.'))]),
        dict(title=text('Sampling: BOUNCE TO PAD','Sampling: BOUNCE TO PAD'),
             intro=text('Bounce records a Sound and its playing Pattern into an empty destination pad. The source instrument, its state and MIDI events remain available. External synthesizers are captured in real time.','Bounce nimmt einen Sound samt laufendem Pattern auf ein leeres Zielpad auf. Quellinstrument, Zustand und MIDI-Events bleiben erhalten. Externe Synthesizer werden in Echtzeit aufgenommen.'),figures=['Sampling / BOUNCE TO PAD'],images=[],
             steps=[variant(text('In RECORD hold SHIFT and press F1 BOUNCE. Select fields with the arrows and edit with the encoder.','Halte in RECORD SHIFT und drücke F1 BOUNCE. Wähle Felder mit den Pfeilen und ändere sie mit dem Encoder.'),text('In RECORD hold SHIFT and press display button 5 BOUNCE. Encoders 1-8 correspond to the eight displayed fields.','Halte in RECORD SHIFT und drücke Displaytaste 5 BOUNCE. Encoder 1-8 gehören zu den acht angezeigten Feldern.')),
                    text('Set SOURCE G and SOURCE PAD. INPUT SOUND captures that Sound including its insert effects and routed external audio. Alternatively choose a direct EXT input. Keep the source Group clip active.','Setze SOURCE G und SOURCE PAD. INPUT SOUND nimmt diesen Sound einschließlich Insert-Effekten und zugeführtem externem Audio auf. Alternativ wählst du einen direkten EXT-Eingang. Der Quell-Group-Clip muss aktiv sein.'),
                    text('Choose TARGET G, TARGET PAD, BARS and RESULT AUDIO or SAMPLER. The target must be empty and different from the source. MIDI REC must be off.','Wähle TARGET G, TARGET PAD, BARS und RESULT AUDIO oder SAMPLER. Das Ziel muss leer sein und sich von der Quelle unterscheiden. MIDI REC muss ausgeschaltet sein.'),
                    text('START arms the bounce and starts PLAY if stopped. It records at the next bar. CANCEL discards it; STOP finishes early. After loading, an AUDIO result follows the target Group Pattern automatically.','START schaltet den Bounce scharf und startet bei Bedarf PLAY. Er nimmt ab dem nächsten Takt auf. CANCEL verwirft ihn, STOP beendet ihn vorzeitig. Nach dem Laden folgt ein AUDIO-Ergebnis automatisch dem Ziel-Group-Pattern.')],
             notes=[(text('Keep the source or mute it','Quelle erhalten oder stummschalten'),text('MUTE SRC defaults OFF. Enable it to mute the original after a successful bounce, otherwise both can play. MIDI and plugin state are kept. A changed target/project is never overwritten; its recording stays in Samples. Loading the file can delay the first audible loop pass.','MUTE SRC ist zunächst OFF. Aktiviere es, um das Original nach erfolgreichem Bounce stummzuschalten; sonst können beide spielen. MIDI und Plug-in-Zustand bleiben erhalten. Ein geändertes Ziel/Projekt wird nicht überschrieben, die Aufnahme bleibt in Samples. Das Laden kann den ersten hörbaren Loop-Durchlauf verzögern.'))])])
